def count_divisors(n):
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        raise ValueError("n must be non-zero")

    count = 0
    for d in range(1, n + 1):
        if n % d == 0:
            count += 1
    return count
